  "support_tickets": {
    "description": "Tickets end to end: list and filter, create for a customer, properties (status, priority, agent, product), tags, watchers, close and re-open, merge and split, bulk actions, custom fields, time tracking, and the FluentCRM, FluentBooking and FluentBoards links on a ticket."
  },
  "support_replies": {
    "description": "Ticket conversations: replies and internal notes, drafts and draft approval, scheduled replies, bulk replies, saved reply templates, and AI reply drafts, summaries and tone.",
    "note": "AI, scheduled replies and bulk replies need Fluent Support Pro."
  },
  "support_customers": {
    "description": "Support customers: find and search, create, update, custom fields, avatars, bulk status changes and deletes."
  },
  "support_agents": {
    "description": "Support staff: agents and their permissions, agent groups, and the signed-in agent's notifications."
  },
  "support_mailboxes": {
    "description": "Business mailboxes (inboxes): CRUD, default mailbox, email notification settings, moving tickets between mailboxes, and email piping status and push endpoints."
  },
  "support_workflows": {
    "description": "Automation workflows: triggers, conditions and action sequences, duplication, run history, and manual runs on selected tickets.",
    "note": "Workflows need Fluent Support Pro."
  },
  "support_reports": {
    "description": "Read-only reporting: overall and per-agent stats, the agent dashboard, ticket and response growth, advanced reports and snapshots, timesheets, and the activity logs."
  },
  "support_products": {
    "description": "Products tickets are filed under, and the ticket tags used to classify them."
  },
  "support_settings": {
    "description": "Global settings: business settings, integrations (FluentCRM, AI provider, cloud uploads, incoming webhook, remote portal), the ticket form, auto-close, activity logging, the Pro license, portal setup and the site-side MCP adapter."
  },
  "support_portal": {
    "description": "The customer-facing side: the customer portal's ticket endpoints (act as the signed-in customer), portal sign-up and login, and the remote portal connection.",
    "note": "customer-portal and auth endpoints run under the portal session policy: with an admin Application Password they act as that user's customer record (none for a pure admin), and signup/login/two_fa/reset_pass check the portal's own nonce, so most are rejected outside a browser."
  },
  "support_utilities": {
    "description": "Maintenance and plumbing: REST connectivity tests, cron and database health, log cleanup, the ticket importer, report data audits, and the public token-authenticated receivers for incoming webhooks, chat replies and OAuth callbacks."
  }
